<?php require 'includes/db.php';require 'includes/functions.php';login_required();$uid=(int)$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$bid=(int)$_POST['book_id'];$s=$conn->prepare('INSERT IGNORE INTO wishlist(user_id,book_id) VALUES(?,?)');$s->bind_param('ii',$uid,$bid);$s->execute();header('Location: wishlist.php');exit;}if(isset($_GET['remove'])){$bid=(int)$_GET['remove'];$s=$conn->prepare('DELETE FROM wishlist WHERE user_id=? AND book_id=?');$s->bind_param('ii',$uid,$bid);$s->execute();}$s=$conn->prepare('SELECT b.* FROM wishlist w JOIN books b ON b.id=w.book_id WHERE w.user_id=?');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$page_title='Wishlist';include 'includes/header.php';?><h1>My Wishlist</h1><div class="grid"><?php while($b=$rows->fetch_assoc()):?><div class="card"><h3><?=e($b['title'])?></h3><p><?=cash($b['price'])?></p><a class="btn" href="book.php?id=<?=$b['id']?>">Details</a> <a href="?remove=<?=$b['id']?>">Remove</a></div><?php endwhile;?></div><?php include 'includes/footer.php';?>
